mapper.select:
SELECT * FROM `wallet_ledger`
WHERE `user_id` = #{userId}
  AND `wallet_type` = #{walletType}

    AND `create_time` >= #{startTime}


    AND `create_time` <= #{endTime}


    AND `biz_type` = #{bizType}

ORDER BY `create_time` DESC

SELECT COALESCE(SUM(change_amount), 0) FROM `wallet_ledger`
WHERE DATE(create_time) = #{date}
  AND `biz_type` = #{bizType}

SELECT COALESCE(SUM(change_amount), 0) FROM `wallet_ledger`
WHERE DATE(create_time) = #{date}
  AND `biz_type` = #{bizType}
  AND `change_amount` > 0

SELECT COALESCE(SUM(change_amount), 0) FROM `wallet_ledger`
WHERE DATE(create_time) = #{date}
  AND `biz_type` = #{bizType}
  AND `change_amount` < 0

SELECT COALESCE(SUM(change_amount), 0) FROM `wallet_ledger`
WHERE `create_time` >= #{startTime}
  AND `create_time` <= #{endTime}
  AND `biz_type` = #{bizType}

SELECT COUNT(DISTINCT user_id) FROM `wallet_ledger`
WHERE `create_time` >= #{startTime}
  AND `create_time` <= #{endTime}
  AND `biz_type` = #{bizType}

SELECT COUNT(*) FROM `wallet_ledger`
WHERE `create_time` >= #{startTime}
  AND `create_time` <= #{endTime}
  AND `biz_type` = #{bizType}

SELECT `user_id` AS `playerId`,
       COALESCE(SUM(CASE WHEN `change_amount` < 0 THEN -`change_amount` ELSE 0 END), 0) AS `totalConsume`,
       COALESCE(SUM(CASE WHEN `change_amount` > 0 THEN `change_amount` ELSE 0 END), 0) AS `giftReceived`
FROM `wallet_ledger`
WHERE `wallet_type` = #{walletType}
  AND `biz_type` = #{bizType}
  AND `create_time` >= #{startTime}
  AND `create_time` < #{endTime}
  AND `user_id` IN

      #{userId}

GROUP BY `user_id`
